package com.mockarena.assessment.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="coding_result_application_receipts",schema="assessment") public class CodingResultApplicationReceipt{@Id private UUID evaluationJobId;private UUID attemptId,questionVersionId;private int globalPosition;private String sourceFingerprint;private Instant createdAt;protected CodingResultApplicationReceipt(){}public CodingResultApplicationReceipt(UUID job,UUID attempt,int position,UUID version,String fingerprint,Instant now){evaluationJobId=job;attemptId=attempt;questionVersionId=version;globalPosition=position;sourceFingerprint=fingerprint;createdAt=now;}public UUID evaluationJobId(){return evaluationJobId;}public UUID attemptId(){return attemptId;}public int globalPosition(){return globalPosition;}public UUID questionVersionId(){return questionVersionId;}public String sourceFingerprint(){return sourceFingerprint;}}
